content.content:
1	package clinical
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"sort"
9		"strings"
10		"time"
11	)
12	
13	// PackageDelivery 是指定接收方取包时得到的视图：交换标识、当前状态、
14	// 创建时间、包内容与摘要，不含内部使用者标识等包外信息。
15	type PackageDelivery struct {
16		ExchangeID ID
17		Status     string
18		Digest     string
19		CreatedAt  time.Time
20		Package    Package
21	}
22	
23	// ReceiptConfirmation 是接收方登记回执后得到的确认。
24	// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
25	// 授权失效或患者停用后登记回执也只返回该确认。
26	type ReceiptConfirmation struct {
27		ExchangeID   ID
28		Status       string
29		Outcome      string
30		RegisteredAt time.Time
31	}
32	
33	// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
34	// 指定接收方。
35	//
36	// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
37	// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
38	// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
39	// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
40	// 不存在或跨患者的引用、夹带草稿、记录不被绑定授权覆盖、授权不符一律拒绝，
41	// 不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
42	//
43	// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
44	// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
45	// 更正或有新版本、新增记录都不会改写已创建的包。
46	//
47	// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
48	// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
49	// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
50	func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
51		if !actor.valid() || !actor.IsInternal() {
52			return Exchange{}, ErrAccessDenied
53		}
54		if patientID == "" {
55			return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
56		}
57		if strings.TrimSpace(receiverID) == "" {
58			return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
59		}
60		if strings.TrimSpace(authorizationID) == "" {
61			return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
62		}
63		if strings.TrimSpace(requestID) == "" {
64			return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
65		}
66		if len(recordIDs) == 0 {
67			return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
68		}
69		for _, rid := range recordIDs {
70			if strings.TrimSpace(rid) == "" {
71				return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
72			}
73		}
74		wanted := uniqueSortedIDs(recordIDs)
75	
76		var result Exchange
77		err := s.mutate(func(snap *snapshot) error {
78			// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
79			// 都只返回原结果（重试不是新建）。
80			if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
81				if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
82					return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
83				}
84				result = *existing
85				if existing.Receipt != nil {
86					r := *existing.Receipt
87					result.Receipt = &r
88				}
89				result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
90				return nil
91			}
92	
93			// 首次创建：患者必须存在且未停用。
94			if _, err := requireActivePatient(snap, patientID); err != nil {
95				return err
96			}
97	
98			// 绑定授权必须存在、属于该患者与接收方、当前有效。
99			a := snap.Authorizations[authorizationID]
100			if a == nil {
101				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
102			}
103			if a.PatientID != patientID {
104				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
105					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
106			}
107			if a.ReceiverID != receiverID {
108				return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
109					ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
110			}
111			now := s.now()
112			if !a.ActiveAt(now) {
113				// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
114				return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
115			}
116	
117			// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
118			pkg := Package{PatientID: patientID, ReceiverID: receiverID}
119			for _, rid := range wanted {
120				r := snap.Records[rid]
121				if r == nil {
122					return fmt.Errorf("%w: record %q", ErrNotFound, rid)
123				}
124				if r.PatientID != patientID {
125					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
126						ErrMismatchedPatient, rid, r.PatientID, patientID)
127				}
128				if r.CurrentVersionID == "" {
129					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
130						ErrInvalidArgument, rid)
131				}
132				v := snap.Versions[r.CurrentVersionID]
133				if v == nil {
134					return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
135				}
136				// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
137				// 同一接收方的其他授权不能补足；夹带一条未覆盖记录即整包拒绝。
138				if !authorizationCoversRecord(a, r) {
139					return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
140						ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
141				}
142				pkg.Records = append(pkg.Records, PackagedRecord{
143					EncounterID: r.EncounterID,
144					Category:    r.Category,
145					RecordID:    r.ID,
146					VersionID:   v.ID,
147					Version:     v.Number,
148					EffectiveAt: v.CreatedAt,
149					Content:     v.Content,
150				})
151			}
152	
153			x := &Exchange{
154				ID:              newID("exch"),
155				PatientID:       patientID,
156				ReceiverID:      receiverID,
157				AuthorizationID: authorizationID,
158				RequestID:       requestID,
159				CreatorID:       actor.ID,
160				Status:          ExchangePending,
161				Digest:          packageDigest(pkg),
162				Package:         pkg,
163				CreatedAt:       now,
164			}
165			snap.Exchanges[x.ID] = x
166			s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
167			result = *x
168			result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
169			return nil
170		})
171		return result, err
172	}
173	
174	// FetchPackage 供指定接收方凭交换标识取包。
175	//
176	// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
177	// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
178	// 是否允许取包按“本次核对时间”判断：请求发出后若因等待同一存储上的其他操作
179	// 而排队，以等待结束、真正开始核对本次取包权限的时刻为准（进入临界区后才
180	// 取样，与接收方 Read 的时间含义一致），提前发出的请求不会延长授权有效期；
181	// 时间窗仍是半开区间 [开始, 截止)，恰好到达截止时刻即失效。授权未开始、
182	// 到期、撤回或患者停用后返回 ErrAccessDenied，交付结果为空，不返回包内容、
183	// 摘要、记录标识或交换状态。
184	// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
185	//
186	// 成功时返回交换创建时固化的包及其摘要与当前状态；此后记录被更正也不会
187	// 重新打包，包内版本与内容仍以创建时保存的为准。
188	func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
189		if !actor.valid() || actor.Kind != "receiver" {
190			return PackageDelivery{}, ErrAccessDenied
191		}
192		if strings.TrimSpace(exchangeID) == "" {
193			return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
194		}
195	
196		var out PackageDelivery
197		err := s.view(func(snap *snapshot) error {
198			// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
199			// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
200			// 是否可取一律按这同一时刻判断，与 Read 的时间含义一致。
201			now := s.now()
202			x := snap.Exchanges[exchangeID]
203			if x == nil || x.ReceiverID != actor.ID {
204				// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
205				return ErrAccessDenied
206			}
207			p := snap.Patients[x.PatientID]
208			if p == nil || p.Deactivated {
209				return ErrAccessDenied
210			}
211			// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
212			a := snap.Authorizations[x.AuthorizationID]
213			if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
214				return ErrAccessDenied
215			}
216			out = PackageDelivery{
217				ExchangeID: x.ID,
218				Status:     x.Status,
219				Digest:     x.Digest,
220				CreatedAt:  x.CreatedAt,
221				Package:    clonePackage(x.Package),
222			}
223			return nil
224		})
225		return out, err
226	}
227	
228	// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
229	// 包摘要、接受或拒绝的结果及原因。
230	//
231	// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。只有指定接收方且摘要
232	// 吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回 ErrConflict，
233	// 状态不变。相同回执（结果与原因均相同）重交返回原确认，不新增审计；结果
234	// 或原因改变返回 ErrConflict。其他身份不能代交，不存在的交换统一拒绝。
235	//
236	// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
237	// 不提供任何受保护内容。
238	func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
239		if !actor.valid() || actor.Kind != "receiver" {
240			return ReceiptConfirmation{}, ErrAccessDenied
241		}
242		if strings.TrimSpace(exchangeID) == "" {
243			return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
244		}
245		if outcome != ReceiptAccepted && outcome != ReceiptRejected {
246			return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
247		}
248		if outcome == ReceiptRejected && strings.TrimSpace(reason) == "" {
249			return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
250		}
251		if outcome == ReceiptAccepted {
252			// 接受不携带原因；统一归一化，保证重复提交判定稳定。
253			reason = ""
254		}
255	
256		var conf ReceiptConfirmation
257		err := s.mutate(func(snap *snapshot) error {
258			x := snap.Exchanges[exchangeID]
259			if x == nil || x.ReceiverID != actor.ID {
260				// 不存在或属于其他接收方/其他身份：统一拒绝。
261				return ErrAccessDenied
262			}
263			if digest != x.Digest {
264				return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
265			}
266			if x.Receipt != nil {
267				if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
268					return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
269				}
270				// 相同回执重交：返回原确认，不新增审计、不改状态。
271				conf = ReceiptConfirmation{
272					ExchangeID:   x.ID,
273					Status:       x.Status,
274					Outcome:      x.Receipt.Outcome,
275					RegisteredAt: x.Receipt.RegisteredAt,
276				}
277				return nil
278			}
279	
280			now := s.now()
281			x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
282			if outcome == ReceiptAccepted {
283				x.Status = ExchangeAccepted
284			} else {
285				x.Status = ExchangeRejected
286			}
287			s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
288			conf = ReceiptConfirmation{
289				ExchangeID:   x.ID,
290				Status:       x.Status,
291				Outcome:      outcome,
292				RegisteredAt: now,
293			}
294			return nil
295		})
296		return conf, err
297	}
298	
299	// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
300	// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
301	// ErrMismatchedPatient。
302	func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
303		if !actor.valid() || !actor.IsInternal() {
304			return Exchange{}, ErrAccessDenied
305		}
306		var result Exchange
307		err := s.view(func(snap *snapshot) error {
308			x, err := requireExchange(snap, patientID, exchangeID)
309			if err != nil {
310				return err
311			}
312			result = cloneExchangeValue(x)
313			return nil
314		})
315		return result, err
316	}
317	
318	// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
319	// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
320	func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
321		if !actor.valid() || !actor.IsInternal() {
322			return nil, ErrAccessDenied
323		}
324		var result []Exchange
325		err := s.view(func(snap *snapshot) error {
326			if _, err := requirePatient(snap, patientID); err != nil {
327				return err
328			}
329			for _, x := range snap.Exchanges {
330				if x.PatientID == patientID {
331					result = append(result, cloneExchangeValue(x))
332				}
333			}
334			sort.Slice(result, func(i, j int) bool {
335				if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
336					return result[i].CreatedAt.Before(result[j].CreatedAt)
337				}
338				return result[i].ID < result[j].ID
339			})
340			return nil
341		})
342		return result, err
343	}
344	
345	func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
346		x := snap.Exchanges[exchangeID]
347		if x == nil {
348			return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
349		}
350		if x.PatientID != patientID {
351			return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
352				ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
353		}
354		return x, nil
355	}
356	
357	func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
358		for _, x := range snap.Exchanges {
359			if x.CreatorID == creatorID && x.RequestID == requestID {
360				return x
361			}
362		}
363		return nil
364	}
365	
366	// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
367	func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
368		if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
369			return false
370		}
371		if len(x.Package.Records) != len(wantedRecordIDs) {
372			return false
373		}
374		// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
375		for i, pr := range x.Package.Records {
376			if pr.RecordID != wantedRecordIDs[i] {
377				return false
378			}
379		}
380		return true
381	}
382	
383	func uniqueSortedIDs(ids []ID) []ID {
384		seen := make(map[ID]struct{}, len(ids))
385		out := make([]ID, 0, len(ids))
386		for _, id := range ids {
387			if _, ok := seen[id]; ok {
388				continue
389			}
390			seen[id] = struct{}{}
391			out = append(out, id)
392		}
393		sort.Strings(out)
394		return out
395	}
396	
397	func clonePackage(p Package) Package {
398		p.Records = append([]PackagedRecord(nil), p.Records...)
399		return p
400	}
401	
402	func cloneExchangeValue(x *Exchange) Exchange {
403		y := *x
404		y.Package = clonePackage(x.Package)
405		if x.Receipt != nil {
406			r := *x.Receipt
407			y.Receipt = &r
408		}
409		return y
410	}
411	
412	// canonicalRecord 固定摘要中每个字段的序列化顺序。
413	type canonicalRecord struct {
414		EncounterID ID     `json:"encounter_id"`
415		Category    string `json:"category"`
416		RecordID    ID     `json:"record_id"`
417		VersionID   ID     `json:"version_id"`
418		Version     int    `json:"version"`
419		EffectiveAt string `json:"effective_at"`
420		Content     string `json:"content"`
421	}
422	
423	type canonicalPackage struct {
424		PatientID  ID                `json:"patient_id"`
425		ReceiverID string            `json:"receiver_id"`
426		Records    []canonicalRecord `json:"records"`
427	}
428	
429	// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
430	// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
431	func packageDigest(p Package) string {
432		cp := canonicalPackage{
433			PatientID:  p.PatientID,
434			ReceiverID: p.ReceiverID,
435			Records:    make([]canonicalRecord, 0, len(p.Records)),
436		}
437		recs := append([]PackagedRecord(nil), p.Records...)
438		sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
439		for _, r := range recs {
440			cp.Records = append(cp.Records, canonicalRecord{
441				EncounterID: r.EncounterID,
442				Category:    r.Category,
443				RecordID:    r.RecordID,
444				VersionID:   r.VersionID,
445				Version:     r.Version,
446				EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
447				Content:     r.Content,
448			})
449		}
450		raw, err := json.Marshal(cp)
451		if err != nil {
452			// 参与序列化的都是字符串/整数等基础类型，不应失败。
453			panic(fmt.Errorf("clinical: cannot marshal package digest: %w", err))
454		}
455		sum := sha256.Sum256(raw)
456		return hex.EncodeToString(sum[:])
457	}
458

file.content:
package clinical

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"
)

// PackageDelivery 是指定接收方取包时得到的视图：交换标识、当前状态、
// 创建时间、包内容与摘要，不含内部使用者标识等包外信息。
type PackageDelivery struct {
	ExchangeID ID
	Status     string
	Digest     string
	CreatedAt  time.Time
	Package    Package
}

// ReceiptConfirmation 是接收方登记回执后得到的确认。
// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
// 授权失效或患者停用后登记回执也只返回该确认。
type ReceiptConfirmation struct {
	ExchangeID   ID
	Status       string
	Outcome      string
	RegisteredAt time.Time
}

// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
// 指定接收方。
//
// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
// 不存在或跨患者的引用、夹带草稿、记录不被绑定授权覆盖、授权不符一律拒绝，
// 不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
//
// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
// 更正或有新版本、新增记录都不会改写已创建的包。
//
// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Exchange{}, ErrAccessDenied
	}
	if patientID == "" {
		return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
	}
	if strings.TrimSpace(receiverID) == "" {
		return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
	}
	if strings.TrimSpace(authorizationID) == "" {
		return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
	}
	if strings.TrimSpace(requestID) == "" {
		return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
	}
	if len(recordIDs) == 0 {
		return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
	}
	for _, rid := range recordIDs {
		if strings.TrimSpace(rid) == "" {
			return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
		}
	}
	wanted := uniqueSortedIDs(recordIDs)

	var result Exchange
	err := s.mutate(func(snap *snapshot) error {
		// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
		// 都只返回原结果（重试不是新建）。
		if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
			if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
				return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
			}
			result = *existing
			if existing.Receipt != nil {
				r := *existing.Receipt
				result.Receipt = &r
			}
			result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
			return nil
		}

		// 首次创建：患者必须存在且未停用。
		if _, err := requireActivePatient(snap, patientID); err != nil {
			return err
		}

		// 绑定授权必须存在、属于该患者与接收方、当前有效。
		a := snap.Authorizations[authorizationID]
		if a == nil {
			return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
		}
		if a.PatientID != patientID {
			return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
				ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
		}
		if a.ReceiverID != receiverID {
			return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
				ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
		}
		now := s.now()
		if !a.ActiveAt(now) {
			// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
			return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
		}

		// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
		pkg := Package{PatientID: patientID, ReceiverID: receiverID}
		for _, rid := range wanted {
			r := snap.Records[rid]
			if r == nil {
				return fmt.Errorf("%w: record %q", ErrNotFound, rid)
			}
			if r.PatientID != patientID {
				return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
					ErrMismatchedPatient, rid, r.PatientID, patientID)
			}
			if r.CurrentVersionID == "" {
				return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
					ErrInvalidArgument, rid)
			}
			v := snap.Versions[r.CurrentVersionID]
			if v == nil {
				return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
			}
			// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
			// 同一接收方的其他授权不能补足；夹带一条未覆盖记录即整包拒绝。
			if !authorizationCoversRecord(a, r) {
				return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
					ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
			}
			pkg.Records = append(pkg.Records, PackagedRecord{
				EncounterID: r.EncounterID,
				Category:    r.Category,
				RecordID:    r.ID,
				VersionID:   v.ID,
				Version:     v.Number,
				EffectiveAt: v.CreatedAt,
				Content:     v.Content,
			})
		}

		x := &Exchange{
			ID:              newID("exch"),
			PatientID:       patientID,
			ReceiverID:      receiverID,
			AuthorizationID: authorizationID,
			RequestID:       requestID,
			CreatorID:       actor.ID,
			Status:          ExchangePending,
			Digest:          packageDigest(pkg),
			Package:         pkg,
			CreatedAt:       now,
		}
		snap.Exchanges[x.ID] = x
		s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
		result = *x
		result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
		return nil
	})
	return result, err
}

// FetchPackage 供指定接收方凭交换标识取包。
//
// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
// 是否允许取包按“本次核对时间”判断：请求发出后若因等待同一存储上的其他操作
// 而排队，以等待结束、真正开始核对本次取包权限的时刻为准（进入临界区后才
// 取样，与接收方 Read 的时间含义一致），提前发出的请求不会延长授权有效期；
// 时间窗仍是半开区间 [开始, 截止)，恰好到达截止时刻即失效。授权未开始、
// 到期、撤回或患者停用后返回 ErrAccessDenied，交付结果为空，不返回包内容、
// 摘要、记录标识或交换状态。
// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
//
// 成功时返回交换创建时固化的包及其摘要与当前状态；此后记录被更正也不会
// 重新打包，包内版本与内容仍以创建时保存的为准。
func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
	if !actor.valid() || actor.Kind != "receiver" {
		return PackageDelivery{}, ErrAccessDenied
	}
	if strings.TrimSpace(exchangeID) == "" {
		return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
	}

	var out PackageDelivery
	err := s.view(func(snap *snapshot) error {
		// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
		// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
		// 是否可取一律按这同一时刻判断，与 Read 的时间含义一致。
		now := s.now()
		x := snap.Exchanges[exchangeID]
		if x == nil || x.ReceiverID != actor.ID {
			// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
			return ErrAccessDenied
		}
		p := snap.Patients[x.PatientID]
		if p == nil || p.Deactivated {
			return ErrAccessDenied
		}
		// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
		a := snap.Authorizations[x.AuthorizationID]
		if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
			return ErrAccessDenied
		}
		out = PackageDelivery{
			ExchangeID: x.ID,
			Status:     x.Status,
			Digest:     x.Digest,
			CreatedAt:  x.CreatedAt,
			Package:    clonePackage(x.Package),
		}
		return nil
	})
	return out, err
}

// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
// 包摘要、接受或拒绝的结果及原因。
//
// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。只有指定接收方且摘要
// 吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回 ErrConflict，
// 状态不变。相同回执（结果与原因均相同）重交返回原确认，不新增审计；结果
// 或原因改变返回 ErrConflict。其他身份不能代交，不存在的交换统一拒绝。
//
// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
// 不提供任何受保护内容。
func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
	if !actor.valid() || actor.Kind != "receiver" {
		return ReceiptConfirmation{}, ErrAccessDenied
	}
	if strings.TrimSpace(exchangeID) == "" {
		return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
	}
	if outcome != ReceiptAccepted && outcome != ReceiptRejected {
		return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
	}
	if outcome == ReceiptRejected && strings.TrimSpace(reason) == "" {
		return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
	}
	if outcome == ReceiptAccepted {
		// 接受不携带原因；统一归一化，保证重复提交判定稳定。
		reason = ""
	}

	var conf ReceiptConfirmation
	err := s.mutate(func(snap *snapshot) error {
		x := snap.Exchanges[exchangeID]
		if x == nil || x.ReceiverID != actor.ID {
			// 不存在或属于其他接收方/其他身份：统一拒绝。
			return ErrAccessDenied
		}
		if digest != x.Digest {
			return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
		}
		if x.Receipt != nil {
			if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
				return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
			}
			// 相同回执重交：返回原确认，不新增审计、不改状态。
			conf = ReceiptConfirmation{
				ExchangeID:   x.ID,
				Status:       x.Status,
				Outcome:      x.Receipt.Outcome,
				RegisteredAt: x.Receipt.RegisteredAt,
			}
			return nil
		}

		now := s.now()
		x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
		if outcome == ReceiptAccepted {
			x.Status = ExchangeAccepted
		} else {
			x.Status = ExchangeRejected
		}
		s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
		conf = ReceiptConfirmation{
			ExchangeID:   x.ID,
			Status:       x.Status,
			Outcome:      outcome,
			RegisteredAt: now,
		}
		return nil
	})
	return conf, err
}

// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
// ErrMismatchedPatient。
func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Exchange{}, ErrAccessDenied
	}
	var result Exchange
	err := s.view(func(snap *snapshot) error {
		x, err := requireExchange(snap, patientID, exchangeID)
		if err != nil {
			return err
		}
		result = cloneExchangeValue(x)
		return nil
	})
	return result, err
}

// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
	if !actor.valid() || !actor.IsInternal() {
		return nil, ErrAccessDenied
	}
	var result []Exchange
	err := s.view(func(snap *snapshot) error {
		if _, err := requirePatient(snap, patientID); err != nil {
			return err
		}
		for _, x := range snap.Exchanges {
			if x.PatientID == patientID {
				result = append(result, cloneExchangeValue(x))
			}
		}
		sort.Slice(result, func(i, j int) bool {
			if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
				return result[i].CreatedAt.Before(result[j].CreatedAt)
			}
			return result[i].ID < result[j].ID
		})
		return nil
	})
	return result, err
}

func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
	x := snap.Exchanges[exchangeID]
	if x == nil {
		return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
	}
	if x.PatientID != patientID {
		return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
			ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
	}
	return x, nil
}

func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
	for _, x := range snap.Exchanges {
		if x.CreatorID == creatorID && x.RequestID == requestID {
			return x
		}
	}
	return nil
}

// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
	if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
		return false
	}
	if len(x.Package.Records) != len(wantedRecordIDs) {
		return false
	}
	// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
	for i, pr := range x.Package.Records {
		if pr.RecordID != wantedRecordIDs[i] {
			return false
		}
	}
	return true
}

func uniqueSortedIDs(ids []ID) []ID {
	seen := make(map[ID]struct{}, len(ids))
	out := make([]ID, 0, len(ids))
	for _, id := range ids {
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		out = append(out, id)
	}
	sort.Strings(out)
	return out
}

func clonePackage(p Package) Package {
	p.Records = append([]PackagedRecord(nil), p.Records...)
	return p
}

func cloneExchangeValue(x *Exchange) Exchange {
	y := *x
	y.Package = clonePackage(x.Package)
	if x.Receipt != nil {
		r := *x.Receipt
		y.Receipt = &r
	}
	return y
}

// canonicalRecord 固定摘要中每个字段的序列化顺序。
type canonicalRecord struct {
	EncounterID ID     `json:"encounter_id"`
	Category    string `json:"category"`
	RecordID    ID     `json:"record_id"`
	VersionID   ID     `json:"version_id"`
	Version     int    `json:"version"`
	EffectiveAt string `json:"effective_at"`
	Content     string `json:"content"`
}

type canonicalPackage struct {
	PatientID  ID                `json:"patient_id"`
	ReceiverID string            `json:"receiver_id"`
	Records    []canonicalRecord `json:"records"`
}

// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
func packageDigest(p Package) string {
	cp := canonicalPackage{
		PatientID:  p.PatientID,
		ReceiverID: p.ReceiverID,
		Records:    make([]canonicalRecord, 0, len(p.Records)),
	}
	recs := append([]PackagedRecord(nil), p.Records...)
	sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
	for _, r := range recs {
		cp.Records = append(cp.Records, canonicalRecord{
			EncounterID: r.EncounterID,
			Category:    r.Category,
			RecordID:    r.RecordID,
			VersionID:   r.VersionID,
			Version:     r.Version,
			EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
			Content:     r.Content,
		})
	}
	raw, err := json.Marshal(cp)
	if err != nil {
		// 参与序列化的都是字符串/整数等基础类型，不应失败。
		panic(fmt.Errorf("clinical: cannot marshal package digest: %w", err))
	}
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

