1	package clinical
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	// dataName 是存放全部业务状态的快照文件名。
15	const dataName = "clinical-data.json"
16	
17	// dataVersion 是快照格式的版本标记，便于将来迁移。
18	const dataVersion = 1
19	
20	// snapshot 是写入磁盘的完整状态。所有业务对象集中在一个文件中，
21	// 采用“临时文件 + 原子改名”整体落盘：成功操作与其审计事件一同保留，
22	// 失败的操作在 mutate 中就已丢弃，不会写出半截状态。
23	type snapshot struct {
24		FormatVersion  int                       `json:"format_version"`
25		Patients       map[string]*Patient       `json:"patients"`
26		Encounters     map[string]*Encounter     `json:"encounters"`
27		Records        map[string]*Record        `json:"records"`
28		Versions       map[string]*Version       `json:"versions"`
29		Authorizations map[string]*Authorization `json:"authorizations"`
30		Exchanges      map[string]*Exchange      `json:"exchanges"`
31		AuditEvents    []*AuditEvent             `json:"audit_events"`
32	}
33	
34	// Clock 决定“发生时间”的来源。生产使用实时时钟；测试可注入固定/可控时钟
35	// 以验证开始、到期、撤回等时间边界。
36	type Clock func() time.Time
37	
38	// Store 是本地临床档案的句柄。数据存放位置由调用方在 Open 时指定。
39	// 同一目录同一时刻只允许一个 Store 打开（通过锁文件互斥）。
40	type Store struct {
41		dir   string
42		clock Clock
43		mu    sync.Mutex
44		lock  *os.File
45		data  *snapshot
46	}
47	
48	// Option 配置 Open 的行为。
49	type Option func(*Store)
50	
51	// WithClock 注入自定义时钟。
52	func WithClock(c Clock) Option {
53		return func(s *Store) { s.clock = c }
54	}
55	
56	// Open 在指定目录打开（必要时创建）本地存储。
57	// 调用方指定数据存放位置；关闭后从同一位置重新打开可看到全部历史，
58	// 到期与否始终按“本次读取时间”重新计算。
59	func Open(dir string, opts ...Option) (*Store, error) {
60		if dir == "" {
61			return nil, fmt.Errorf("%w: empty data directory", ErrInvalidArgument)
62		}
63		if err := os.MkdirAll(dir, 0o755); err != nil {
64			return nil, err
65		}
66	
67		lockPath := filepath.Join(dir, ".clinical.lock")
68		lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
69		if err != nil {
70			return nil, err
71		}
72		if err := tryLockFile(lockFile); err != nil {
73			lockFile.Close()
74			return nil, err
75		}
76	
77		s := &Store{dir: dir, clock: time.Now, lock: lockFile}
78		for _, opt := range opts {
79			opt(s)
80		}
81		if s.clock == nil {
82			s.clock = time.Now
83		}
84	
85		if err := s.loadLocked(); err != nil {
86			unlockFile(lockFile)
87			lockFile.Close()
88			return nil, err
89		}
90		return s, nil
91	}
92	
93	func (s *Store) loadLocked() error {
94		path := filepath.Join(s.dir, dataName)
95		raw, err := os.ReadFile(path)
96		if os.IsNotExist(err) {
97			s.data = newSnapshot()
98			return nil
99		}
100		if err != nil {
101			return err
102		}
