package clinical

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestRetrySucceedsWhileSaveBlocked(t *testing.T) {
	dir := t.TempDir()
	clk := time.Date(2026, 5, 1, 9, 0, 0, 0, time.UTC)
	s, err := Open(dir, WithClock(func() time.Time { return clk }))
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()

	p, _ := s.RegisterPatient(doc, "患者")
	e, _ := s.AddEncounter(doc, p.ID, time.Time{})
	rd, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "内容")
	s.ActivateRecord(doc, rd.ID)
	a, _ := s.GrantSelective(doc, p.ID, rcv.ID, nil,
		[]RecordSelection{{EncounterID: e.ID, Category: Diagnosis, RecordID: rd.ID}},
		clk.Add(-time.Hour), clk.Add(48*time.Hour))

	x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID}, "req-1")
	if err != nil {
		t.Fatal(err)
	}
	// 接收方登记拒绝回执
	if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "原因"); err != nil {
		t.Fatal(err)
	}

	// 阻断本地保存
	dataPath := filepath.Join(dir, dataName)
	backup := dataPath + ".saved"
	os.Rename(dataPath, backup)
	os.Mkdir(dataPath, 0o755)
	defer func() {
		os.Remove(dataPath)
		os.Rename(backup, dataPath)
	}()

	// 同请求号同参数重试：即使保存不可用也必须成功返回原交换（含回执）
	retry, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID, rd.ID}, "req-1")
	if err != nil {
		t.Fatalf("retry must succeed despite save failure: %v", err)
	}
	if retry.ID != x.ID || retry.Status != ExchangeRejected || retry.Receipt == nil ||
		retry.Receipt.Reason != "原因" || retry.Digest != x.Digest ||
		!retry.CreatedAt.Equal(x.CreatedAt) {
		t.Fatalf("retry returned wrong exchange: %+v", retry)
	}
	// 返回独立副本：修改不影响正式数据
	retry.Package.Records[0].Content = "篡改"
	retry.Receipt.Reason = "篡改"
	again, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID}, "req-1")
	if err != nil || again.Package.Records[0].Content != "内容" || again.Receipt.Reason != "原因" {
		t.Fatalf("stored exchange mutated via returned copy: %+v %v", again, err)
	}

	// 同请求号不同参数：仍返回 ErrConflict，不能改报保存错误
	_, err = s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID, rd.ID, rd.ID}, "req-1")
	if err != nil {
		t.Fatalf("same set with different duplicates should be equal: %v", err)
	}
	rd2, _ := s.CreateDraft(doc, p.ID, e.ID, Order, "医嘱")
	s.ActivateRecord(doc, rd2.ID)
	if _, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID, rd2.ID}, "req-1"); !errors.Is(err, ErrConflict) {
		t.Fatalf("different record set must be ErrConflict, got %v", err)
	}

	// 无对应成功交换的新请求号：保存失败必须返回实际错误
	if _, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID}, "req-new"); err == nil ||
		errors.Is(err, ErrConflict) || errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrAccessDenied) {
		t.Fatalf("first create with blocked save must return raw save error, got %v", err)
	}
}
EOF
